// Vitrines · Envoi (01/10/2026). pause : rien ne part ; test : tout part vers l'adresse de test de Basile (marqué « teste ») ;
// live : vers le commerçant, jamais le week-end. Le texte vient tel quel du brouillon validé par Basile (agents/vitrines.js).
const cfg = ($('Lire config').first() || { json: {} }).json || {};
const mode = cfg.mode || 'pause';
if (mode !== 'live' && mode !== 'test') return [];
const jour = new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris', weekday: 'short' });
if (mode === 'live' && (jour === 'Sat' || jour === 'Sun')) return [];
if (mode === 'test' && !cfg.test_to) return [];
const fromEmail = cfg.from_email || 'contact@raime.fr';
const fromName = cfg.from_name || 'rAIme';
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const liens = (s) => s.replace(/https:\/\/[^\s<]+/g, (u) => '<a href="' + u + '">' + u + '</a>');
const NL = String.fromCharCode(10);
const out = [];
for (const it of $('A envoyer').all()) {
  const d = it.json || {};
  if (!d.id || !d.to_email || !d.corps) continue;
  const desinscription = 'https://cockpit.raime.fr/unsub?e=' + encodeURIComponent(d.to_email);
  const essai = mode === 'test' ? ' · [ESSAI : destinataire réel ' + esc(d.to_email) + ']' : '';
  const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:15px;line-height:1.6;color:#1a1a1a">'
    + liens(esc(d.corps)).split(NL).join('<br>')
    + '<p style="font-size:11px;color:#999999;margin-top:22px">' + esc(fromEmail) + essai
    + ' · <a href="' + desinscription + '" style="color:#999999">se désinscrire</a></p></div>';
  out.push({ json: { id: d.id, mode, email_body: {
    from: fromName + ' <' + fromEmail + '>',
    to: [mode === 'live' ? d.to_email : cfg.test_to],
    reply_to: fromEmail,
    subject: (mode === 'test' ? '[ESSAI] ' : '') + (d.sujet || 'Votre site'),
    html,
    text: d.corps + NL + NL + 'Se désinscrire : ' + desinscription,
    headers: { 'List-Unsubscribe': '<' + desinscription + '>' },
  } } });
}
return out;

// Chaque e-mail est marqué selon SA réponse de Resend : un refus au milieu du lot n'efface pas les envois réussis
// (sinon ils repartiraient le lendemain). Un essai (mode test) n'est jamais compté comme un envoi.
const envois = $('Prepare').all();
const reponses = $input.all();
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const lignes = [];
envois.forEach((e, i) => {
  const id = parseInt(e.json.id);
  if (isNaN(id)) return;
  const r = (reponses[i] || { json: {} }).json || {};
  const ok = typeof r.id === 'string' && /^[A-Za-z0-9-]{8,64}$/.test(r.id) && !r.statusCode && !r.error;
  const statut = ok ? (e.json.mode === 'live' ? 'envoye' : 'teste') : 'erreur';
  const erreur = ok ? null : String(r.message || (r.error && (r.error.message || r.error)) || 'réponse inattendue de Resend').slice(0, 200);
  lignes.push('(' + id + ',' + q(statut) + ',' + (ok ? q(r.id) : 'NULL') + ',' + (erreur === null ? 'NULL' : q(erreur)) + ')');
});
if (!lignes.length) return [];
const sql = 'UPDATE vitrines_envoi e SET statut = v.statut::text, resend_id = v.resend_id::text, erreur = v.erreur::text, '
  + "envoye_le = CASE WHEN v.statut::text <> 'erreur' THEN now() END, maj_le = now() "
  + 'FROM (VALUES ' + lignes.join(',') + ") AS v(id, statut, resend_id, erreur) WHERE e.id = v.id AND e.statut = 'a_envoyer';";
return [{ json: { sql, count: lignes.length } }];
